<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Project Atlas — Report Copilot</title>
<style>body{font:16px system-ui;background:#f3f6fa;color:#172b4d;margin:0}.wrap{max-width:850px;margin:40px auto;padding:24px}.card{background:white;border:1px solid #dbe3ed;border-radius:14px;padding:22px;margin:16px 0;box-shadow:0 4px 14px #2030440c}textarea{width:100%;box-sizing:border-box;min-height:110px;padding:12px;border:1px solid #c4cfdd;border-radius:8px;font:inherit}button,select{padding:10px 14px;border-radius:7px;border:1px solid #aab8ca;background:#fff;font:inherit}button{background:#1957a6;color:white;border:0;cursor:pointer}.answer{white-space:pre-wrap}.muted{color:#64748b;font-size:14px}</style></head>
<body><main class="wrap"><h1>Project Atlas — Report Copilot</h1><p class="muted">Demo client selector. A production portal must supply client identity from its authenticated session.</p>
<form method="get" action="/copilot"><label>Demo client <select name="demo_client" onchange="this.form.submit()"><option value="C-01" <?= $client_id==='C-01'?'selected':'' ?>>Northwind Utilities (C-01)</option><option value="C-02" <?= $client_id==='C-02'?'selected':'' ?>>Blue Delta Infra (C-02)</option></select></label></form>
<?php if (!empty($history)): ?><section class="card"><h2>Conversation history</h2><?php foreach ($history as $entry): ?><p><strong><?= html_escape(ucfirst($entry['role'])) ?>:</strong> <span class="answer"><?= html_escape($entry['content']) ?></span></p><?php endforeach; ?></section><?php endif; ?>
<section class="card"><form method="post" action="/copilot/chat"><?= form_hidden($this->security->get_csrf_token_name(), $this->security->get_csrf_hash()) ?><input type="hidden" name="client_id" value="<?= html_escape($client_id) ?>"><label for="message">Ask about your reports</label><textarea id="message" name="message" maxlength="4000" required></textarea><p><button type="submit">Ask Report Copilot</button></p></form></section>
<?php if (is_array($result)): ?><section class="card"><h2>Response</h2><div class="answer"><?= html_escape($result['answer'] ?? '') ?></div>
<p class="muted">Confidence: <?= html_escape((string)round(($result['confidence'] ?? 0) * 100)) ?>% · <?= !empty($result['escalated']) ? 'Escalated to analyst' : 'Not escalated' ?></p>
<?php if (!empty($result['citations'])): ?><h3>Sources</h3><ul><?php foreach ($result['citations'] as $citation): ?><li><?= html_escape($citation['report_id'] . ', p.' . $citation['page'] . ' — ' . $citation['report_title']) ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php if (!empty($result['conflicts'])): ?><h3>Conflicts</h3><ul><?php foreach ($result['conflicts'] as $conflict): ?><li><?= html_escape($conflict) ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php if (!empty($result['derived_values'])): ?><h3>Derived values</h3><ul><?php foreach ($result['derived_values'] as $derived): ?><li><?= html_escape(json_encode($derived)) ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php if (!empty($result['message_id']) && !empty($result['conversation_id'])): ?><form method="post" action="/copilot/feedback"><?= form_hidden($this->security->get_csrf_token_name(), $this->security->get_csrf_hash()) ?><input type="hidden" name="message_id" value="<?= (int)$result['message_id'] ?>"><input type="hidden" name="conversation_id" value="<?= html_escape($result['conversation_id']) ?>"><button name="rating" value="1">👍</button> <button name="rating" value="-1">👎</button></form><?php endif; ?>
</section><?php endif; ?>
</main></body></html>
